export function collection(items, page = 1, pageSize = 100) {
  return {
    items,
    page: { page, page_size: pageSize, total: items?.length ?? 0 },
  };
}
export function message(index) {
  return {
    id: `a0000000-0000-4000-8000-${String(index).padStart(12, "0")}`,
    conversation_id: conversation.id,
    sender_id: user.id,
    body: `Mensagem ${index}`,
    created_at: new Date(Date.UTC(2026, 0, 1, 0, index)).toISOString(),
    deleted_at: null,
    edited_at: null,
    moderated_at: null,
    moderated_by: null,
    moderation_status: "approved",
    moderation_reason: null,
  };
}
